def vertical_period(grid):
    """The smallest p such that every pair of rows holding the non-background color and congruent mod p has one's non-background column set contained in the other's."""
    from collections import Counter
    h,w=len(grid),len(grid[0])
    cnt=Counter(v for row in grid for v in row)
    bg=cnt.most_common(1)[0][0]
    c=next(v for v in cnt if v!=bg)
    R=[r for r in range(h) if c in grid[r]]
    cs={r:{j for j in range(w) if grid[r][j]==c} for r in R}
    p=1
    while not all(cs[a]<=cs[b] or cs[b]<=cs[a] for i,a in enumerate(R) for b in R[i+1:] if a%p==b%p):
        p+=1
    return p,bg,c,R,cs

def complete_periodic_noise(grid, new=1):
    """A pattern repeated with a vertical period: background cells inside the union of a stripe's positions become new, and extra pattern-color noise is repainted new at its position shifted into the first period."""
    p,bg,c,R,cs=vertical_period(grid)
    ref={}
    for r in R: ref.setdefault(r%p,set()).update(cs[r])
    out=[row[:] for row in grid]
    for r in R:
        for j in ref[r%p]:
            if out[r][j]==bg: out[r][j]=new
    for r in R:
        for j in cs[r]:
            if j not in ref[r%p] and out[r%p][j]==bg: out[r%p][j]=new
    return out

